"""Explain RCU put context and per-CPU local locks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1401': ('빌리지 않은 물건을 또 반납하거나, 셈이 넘친 장부를 계속 줄여 버리려 하면 문제가 생깁니다. 이 코드는 그런 상태에서 물건을 버리지 못하게 합니다.', '포화와 불균형 반납의 복구가 파괴 허가와 다른 이유를 이해합니다.', 'NOREF가 아닌 종료 구역 → DEAD·false, 포화 구역 → SATURATED·false, 다시 관측한 일반 구역 → 그대로·false라는 세 줄 표를 만드세요.', ['put은 보유한 참조 하나를 놓는 동작입니다. 참조를 얻은 만큼 올바르게 놓아야 합니다. rcuref_put_slowpath는 먼저 NOREF인지 검사해 마지막 상태 확정을 시도합니다. 이 수업은 그 특별한 분기를 지난 나머지 경우를 봅니다.', 'NOREF가 아닌데 cnt >= RELEASED이면 종료 구역에서 또 반납하려는 불균형 상태입니다. WARN_ONCE로 경고 조건을 확인하고 DEAD로 되돌린 뒤 false를 반환합니다. 경고가 있다고 잘못된 호출을 정상 사용법으로 바꿔 주는 것은 아닙니다.', '종료 구역 아래이지만 MAXREF보다 크면 포화 구역입니다. 너무 큰 참조 수 때문에 정확한 셈 대신 특별 상태를 유지하는 경우입니다. 값을 SATURATED로 되돌리고 false를 반환합니다.', '포화에서 한 번 줄였다고 정상 참조 수로 복원되거나 마지막 사용자가 끝난 것은 아닙니다. 이 구현은 너무 큰 수가 작은 수로 돌아가 잘못 해제되는 일을 막으려고 메모리를 남깁니다. 반복 put으로 억지로 해제하려 하면 안 됩니다.', '다른 실행 흐름의 증감 때문에 새로 읽은 값이 일반 구역이면 별도 대입 없이 false로 끝납니다. 처음 별도 처리가 필요했던 결과와 나중 관측한 값은 다를 수 있습니다.', '따라서 false의 이유는 하나가 아닙니다. 참조가 남음, 경쟁, 포화, 불균형 등 여러 경우가 있지만 공통 약속은 이 호출자가 객체를 파괴하지 말라는 것입니다. false를 정확한 보유자 수나 이미 반납 완료라는 뜻으로 읽지 마세요.'], [('포화 상태에서 put을 한 번 하면 파괴 허가 true가 나올까요?', ['네. 한 번 줄이면 언제나 마지막이에요', '아니요. 포화 표시를 복구하고 false를 반환해요'], '포화는 정상적인 정확한 수가 아닙니다. 잘못된 해제를 막기 위해 SATURATED로 되돌리고 객체를 파괴하지 못하게 합니다.'), ('put의 false는 활성 사용자가 반드시 정확히 하나 있다는 뜻일까요?', ['아니요. 포화나 경쟁 같은 다른 이유도 있어요', '네. 언제나 실제 사용자가 정확히 하나예요'], '반환은 이 호출에 파괴를 허용하는지 알려 줍니다. 실제 수를 반환하는 함수가 아니며 여러 상태에서 false가 나옵니다.')]), 'os1402': ('책을 반납 처리하는 동안 다른 담당자가 책을 먼저 치우면, 아직 처리 중인 사람이 사라진 책을 만질 수 있습니다. 안전한 처리 구간이 먼저 마련되어 있어야 합니다.', 'put_rcusafe의 호출 문맥과 접근 순서·객체 수명의 차이를 배웁니다.', '책 내용 읽기 순서 보장과 책이 아직 남아 있도록 보장이라는 두 칸을 적으세요. release/acquire는 첫째, 적절한 RCU 보호 문맥은 둘째 역할에 연결하세요.', ['rcuref_put_rcusafe는 return __rcuref_put(ref) 한 줄로 내부 처리에 연결합니다. 이름에 safe가 있지만 함수가 스스로 모든 안전 조건을 만드는 것은 아닙니다. 호출하는 쪽에 이미 필요한 보호가 있어야 합니다.', 'RCU의 grace period는 이전부터 읽던 쪽의 사용이 끝나기를 기다리는 기간입니다. 조건이 충족되면 미뤄 둔 메모리 반납이 진행될 수 있습니다. 아직 put이 객체를 만지는 중인데 그 객체 반납이 끝나면 안 됩니다.', '마지막 감소 뒤 다른 get·put 쌍이 들어와 종료를 확정할 수 있습니다. 원래 put의 별도 처리가 끝나기 전에 그 경쟁자가 예약한 반납까지 끝나지 않도록, 관련 grace period 완료를 막는 문맥이 필요합니다.', '문서는 rcu_read_lock으로 보호된 읽기 구간과 적절한 atomic 문맥을 예로 듭니다. 여기서 atomic 문맥은 잠들거나 일반 작업처럼 선점될 수 없는 등의 제약이 있는 실행 상황입니다. 원자 연산 하나를 호출했다는 뜻과는 다릅니다.', '이 wrapper 안에는 preempt_disable이 없습니다. 이미 안전한 문맥을 이용하는 것이므로 임의의 선점 가능한 코드에서 이름만 믿고 호출하면 안 됩니다. 일반적인 호출에는 필요한 구간 보호를 더하는 rcuref_put을 사용합니다.', '감소의 release와 마지막 성공의 acquire는 메모리 접근 순서를 맞춥니다. 순서가 맞아도 접근할 객체 자체가 없어지면 안전하지 않습니다. 문맥 보호와 순서 보장을 함께 지키고, true 뒤에도 해당 객체의 RCU 제거·반납 규칙을 따라야 합니다.'], [('put_rcusafe는 내부에서 언제나 preempt_disable을 호출할까요?', ['네. 일반 put과 똑같이 직접 금지해요', '아니요. 호출 문맥에 이미 필요한 보호가 있어야 해요'], '본문은 내부 helper를 바로 호출합니다. 일반 put의 선점 금지 코드는 없으므로 바깥 문맥이 관련 수명 보호 조건을 제공해야 합니다.'), ('release/acquire 순서만 있으면 객체가 반납되지 않는 조건도 자동 충족될까요?', ['아니요. RCU 문맥의 수명 보호도 필요해요', '네. 접근 순서와 객체 수명은 같은 조건이에요'], '어떤 순서로 읽는지와 읽을 메모리가 남아 있는지는 다른 문제입니다. 순서가 맞아도 메모리가 사라지면 잘못된 접근이 됩니다.')]), 'os1403': ('반납 장부를 고치다 잠깐 자리를 비운 사이 다른 사람이 마지막 정리를 끝낼 수 있습니다. 아직 남은 처리가 사라진 물건을 만지지 않도록 구간 전체를 보호합니다.', '일반 put이 내부 처리 전후에 선점을 제어하는 이유를 이해합니다.', '선점 금지 횟수가 2라면 시작 때 3, 내부 감소와 마지막 판정 동안 3, 끝에서 2로 복귀한다고 적으세요. 반환 뒤까지 이 추가 금지를 유지하는 것은 아닙니다.', ['rcuref_put은 먼저 preempt_disable을 호출하고 내부 __rcuref_put을 수행한 뒤 preempt_enable을 호출합니다. released라는 변수에 내부 반환값을 보관했다가 그대로 돌려줍니다. 내부 함수가 false여도 금지 복구 단계를 거칩니다.', '선점은 실행 중인 작업을 잠시 멈추고 다른 작업이 CPU를 사용하도록 바꾸는 것입니다. 이 함수는 감소만 아니라 별도 처리의 마지막 비교까지 포함해 내부 호출 전체를 보호합니다.', '보호가 없다는 가정에서 A가 마지막 감소로 NOREF를 만든 뒤 선점되었다고 합시다. B가 get으로 참조를 얻고 다시 put하여 DEAD를 확정한 뒤 RCU 반납을 예약할 수 있습니다.', '그 사이 grace period가 끝나 메모리가 반납되면 A가 돌아와 아직 하려던 CAS를 수행할 때 이미 사라진 객체를 만지게 됩니다. CAS는 예상값을 비교하는 기술이지만, 주소의 수명 자체가 끝난 문제까지 해결하지 못합니다.', '원문은 put 전체 동안 선점을 금지해 관련 grace period가 완료되어 객체가 사라지는 경쟁을 막는다고 설명합니다. 이 보호는 다른 CPU의 모든 실행을 멈추는 전역 잠금이 아닙니다. get·put 사이 경쟁은 여전히 상태 비교로 처리합니다.', '선점 금지는 중첩될 수 있습니다. 원래 횟수 2라면 3으로 늘었다가 2로 돌아갑니다. enable이 언제나 0으로 만드는 것은 아닙니다. true일 때만 상위의 마지막 처리를 진행하며, 함수 반환 후의 반납 절차도 RCU 규칙을 따라야 합니다.'], [('일반 put의 선점 보호는 어느 부분을 감쌀까요?', ['함수 반환 후 free만 보호해요', '내부 감소와 마지막 별도 판정까지 보호해요'], 'preempt_disable은 내부 helper 앞, preempt_enable은 그 뒤에 있습니다. helper가 마지막 CAS를 수행하는 시간도 포함됩니다.'), ('원래 선점 금지 횟수가 2이면 정상 반환 후 몇으로 돌아갈까요?', ['2로 돌아가요', '반드시 0으로 바뀌어요'], '이번 호출이 한 번 더해 3을 만들고 한 번 되돌려 2가 됩니다. 기존 금지 이유까지 취소하지 않습니다.')]), 'os1404': ('교실마다 따로 있는 공책을 생각해 봅시다. 우리 교실 공책을 보호하는 규칙은 다른 교실 공책까지 한꺼번에 잠그는 규칙과 다릅니다.', 'CPU별 자료 보호와 설정에 따라 달라지는 local_lock 구현을 이해합니다.', 'CPU 0의 공책과 CPU 1의 공책을 따로 그리세요. CPU 0의 local_lock은 CPU 0 쪽 잠금과 연결된다고 표시하세요. 다른 CPU 자료까지 전역으로 막는 화살표는 그리지 마세요.', ['per-CPU 자료는 CPU마다 따로 둔 복사본입니다. 여러 CPU가 항상 하나의 공용 숫자를 고치지 않아도 되도록 각자의 자료를 둘 수 있습니다. 그래도 같은 CPU에서 실행되는 여러 작업이나 인터럽트 사이에는 보호가 필요할 수 있습니다.', 'local_lock은 이런 CPU별 자료의 보호 구간에 이름을 붙인 API입니다. this_cpu_ptr는 현재 CPU에 해당하는 저장 위치를 고릅니다. 잠금 변수도 올바른 per-CPU 저장 형태로 준비하고 그 자료를 만지는 문맥에 맞게 사용해야 합니다.', '공개 헤더는 local_lock, local_lock_irq, irqsave, unlock, irqrestore 같은 이름을 내부 __local 함수·매크로로 연결합니다. wrapper는 바깥에 같은 이름을 제공하면서 안쪽 구현을 선택하게 하는 연결층입니다.', '일반적인 non-RT 구성의 기본 local_lock은 preempt_disable로 선점을 금지하고 현재 CPU 잠금의 분석 정보를 관리합니다. 디버그 설정에 따라 기록 부분이 달라집니다. 모든 구성에서 보통의 전역 spinlock을 잡는 코드가 있는 것은 아닙니다.', 'PREEMPT_RT 구성에서는 기본 경로가 migrate_disable 뒤 현재 CPU의 spinlock을 잡습니다. migration은 실행이 다른 CPU로 옮겨가는 것입니다. 여기서는 CPU 이동을 막고 CPU별 잠금으로 보호하면서 선점 가능한 구조를 사용합니다. IRQ 이름도 RT에서 동일한 인터럽트 차단 명령을 뜻하지 않으므로 내부 분기를 확인해야 합니다.', 'IRQ는 인터럽트, BH는 softirq 같은 후속 처리 문맥과 관련된 이름입니다. 어느 문맥이 같은 자료를 만지는지에 맞는 변형과 대응 해제를 골라야 합니다. 다른 CPU의 복사본이나 전역 자료까지 이 local 보호 하나로 안전해진다고 가정하면 안 됩니다.'], [('local_lock이 기본적으로 연결하는 자료는 무엇일까요?', ['모든 CPU가 공유하는 하나의 전역 mutex예요', '현재 CPU에 속한 local 자료예요'], 'this_cpu_ptr가 현재 CPU의 잠금 위치를 고릅니다. CPU별 자료 보호와 모든 CPU의 작업을 하나로 직렬화하는 전역 잠금은 다릅니다.'), ('같은 local_lock 이름이면 RT와 일반 구성에서 언제나 같은 명령을 실행할까요?', ['아니요. 설정에 따라 내부 구현이 달라요', '네. 언제나 preempt_disable 한 줄뿐이에요'], '일반 기본 경로는 선점 제어, RT 기본 경로는 이동 제어와 CPU별 spinlock을 사용합니다. 같은 공개 이름의 기능을 각 구성에 맞게 구현하는 것입니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_346.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
